131:     ///
132:     /// Use [`CommitBuilder`] to commit the transaction.
133:     ///
134:     /// # Example: Append data to a dataset
135:     ///
136:     /// ```rust
137:     /// use lance::dataset::{CommitBuilder, InsertBuilder, WriteMode, WriteParams};
138:     ///
139:     /// # use std::sync::Arc;
140:     /// # use arrow_array::RecordBatch;
141:     /// # use lance::Result;
