143:     /// # async fn example(dataset: Arc<Dataset>, data: Vec<RecordBatch>) -> Result<()> {
144:     /// let transaction = InsertBuilder::new(dataset.clone())
145:     ///     .with_params(&WriteParams { mode: WriteMode::Append, ..Default::default() })
146:     ///     .execute_uncommitted(data)
147:     ///     .await?;
148:     /// CommitBuilder::new(dataset)
149:     ///     .execute(transaction)
150:     ///     .await?;
