158:     async fn do_commit(
159:         &self,
160:         context: &WriteContext<'_>,
161:         transaction: Transaction,
162:     ) -> Result<Dataset> {
163:         let mut commit_builder = CommitBuilder::new(context.dest.clone())
164:             .use_stable_row_ids(context.params.enable_stable_row_ids)
165:             .with_exact_storage_format(context.storage_version)
166:             .enable_v2_manifest_paths(context.params.enable_v2_manifest_paths)
167:             .with_commit_handler(context.commit_handler.clone())
168:             .with_object_store(context.object_store.clone())
169:             .with_skip_auto_cleanup(context.params.skip_auto_cleanup);
170: 
171:         if let Some(params) = context.params.store_params.as_ref() {
172:             commit_builder = commit_builder.with_store_params(params.clone());
173:         }
174: 
175:         if let Some(session) = context.params.session.as_ref() {
176:             commit_builder = commit_builder.with_session(session.clone());
177:         }
178:         if self.keep_field_ids {
179:             commit_builder = commit_builder.with_table_field_ids();
180:         }
181: 
182:         commit_builder.execute(transaction).await
183:     }

